end
cgb=cgb+1
task.wait(3.5)
continue
end
while U.now()-mgb<5 and(tonumber((Wfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Xfb).xp)or 0)<=lgb do
task.wait(0.1)
end
local pgb=tonumber((Wfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Xfb).xp)or 0
if pgb>lgb then
bgb=bgb+1
for qgb,rgb in ipairs(jgb)do
dgb[rgb]=true
end
cb.add(string.format(xke[3153],#jgb,Yfb),#jgb,xke[3154],string.format(xke[3155],U.fmt(pgb-lgb)))
F.log(1,xke[2520],string.format(xke[3156],#jgb,Yfb,U.fmt(pgb-lgb),kb.level(Wfb.collection:get_unit_by_uuid(O.fuseXpUnit)or Xfb)))
