for xxb,yxb in pairs(pxb.profile_data.collection.owned_units)do
local zxb=yxb.unit_id
if not rxb[xxb]and not rxb[zxb]and N.Units[zxb]and not V.isFarm(zxb)and not V.allyBuff(zxb)and os.time()-(tonumber(oxb.tried[zxb])or 0)>ab.LAB.AGAIN then
