local Cxb=kb.score(Bxb)
if Cxb>0 and(not uxb or Axb<vxb or(Axb==vxb and Cxb>wxb))then
uxb,vxb,wxb={uuid=xxb,id=zxb,u=Bxb},Axb,Cxb
end
end
end
end
if not uxb then
return
end
local Dxb,Exb
for Fxb,Gxb in ipairs(qxb)do
if not V.isFarm(Gxb.id)and not V.allyBuff(Gxb.id)and Gxb.uuid~=O.evolveUnit then
local Hxb=kb.score(Gxb.u)
if not Dxb or Hxb<Exb then
Dxb,Exb=Gxb,Hxb
end
end
end
if not Dxb then
