end
oxb.tried[uxb.id]=os.time()
local Ixb=0
for Jxb in pairs(oxb.tried)do
Ixb=Ixb+1
if Ixb>300 then
oxb.tried[Jxb]=nil
end
end
local Kxb,Lxb=gb.levelFor(nxb)
if not Kxb then
return
end
local Mxb=gb.info(Kxb,nxb.key,Lxb,nxb.mod or W.ldMod(Kxb)or W.levelMod(nxb.level))
local Nxb={}
for Oxb,Pxb in ipairs(qxb)do
