end
local Qxb,Rxb=pcall(gb.run,Mxb,gb.teamFrom(Nxb,Mxb.map),{hpMul=1.1})
local Sxb=Qxb and type(Rxb)==xke[2016]and(Rxb.won or(Mxb.infinite and(tonumber(Rxb.wave)or 0)>=0.8*W.infReach(nxb.key)))
if not Sxb then
