return
end
local Txb={}
for Uxb,Vxb in ipairs(qxb)do
table.insert(Txb,Vxb.uuid==Dxb.uuid and uxb.uuid or Vxb.uuid)
end
if ab.equipTeam(Txb,xke[3548]..V.name(uxb.id))then
oxb.now={id=uxb.id,out=Dxb.id,key=nxb.key,at=os.time(),ev=vxb}
