function eb.upgradeGain(DBb,EBb,FBb,GBb,HBb,IBb)
local JBb,KBb=EBb[FBb],EBb[FBb+1]
local LBb=(JBb.cd>0 and JBb.damage/JBb.cd or 0)
local MBb=(KBb.cd>0 and KBb.damage/KBb.cd or 0)*V.aoe(KBb.atk,KBb.range)/math.max(0.3,V.aoe(JBb.atk,JBb.range))
local NBb=LBb>0 and DBb*(MBb/LBb-1)or(IBb or 0)
local OBb=EBb[FBb+2]
if OBb and FBb+1<EBb.max and OBb.cd>0 and KBb.cd>0 and LBb>0 then
local PBb=DBb*((OBb.damage/OBb.cd)/LBb-1)
local QBb=GBb+OBb.cost*HBb
if PBb/QBb>NBb/GBb then
NBb=NBb+(PBb/QBb*GBb-NBb)*0.5
end
end
local RBb=(KBb.range or 0)>(JBb.range or 0)and(1+((KBb.range-JBb.range)/math.max(1,JBb.range)))or 1
return math.max(0,NBb)*RBb
end
function eb.dpsFor(SBb,TBb)
if TBb<=0 then
return 0
end
local UBb={}
for VBb,WBb in ipairs(SBb)do
if not WBb.farm and WBb.gain>0 then
table.insert(UBb,WBb)
end
end
table.sort(UBb,function(XBb,YBb)
return XBb.gain/XBb.cost>YBb.gain/YBb.cost
end)
local ZBb,_Bb=0,0
for aCb,bCb in ipairs(UBb)do
if TBb<=0 then
break
end
_Bb=bCb.gain/bCb.cost
local cCb=math.min(1,TBb/bCb.cost)
ZBb=ZBb+bCb.gain*cCb
TBb=TBb-bCb.cost*cCb
end
return ZBb+math.max(0,TBb)*_Bb*0.7
end
function eb.shieldDps(dCb,eCb,fCb,gCb,hCb,iCb,jCb)
if(gCb or 0)<=0 or(dCb or 0)<=0 or(hCb or 0)<=0 then
return dCb or 0
end
eCb,fCb,iCb=math.max(0.3,eCb or 2),math.max(1,fCb or 1),iCb or 1
local kCb=dCb*iCb*eCb/fCb
return hCb*fCb/((gCb/math.max(1,jCb or 1)+math.max(1,hCb/kCb))*eCb)/iCb
end
function eb.shieldGain(lCb,mCb,nCb,oCb,pCb,qCb,rCb,sCb)
local tCb,uCb=V.attackInfo(mCb.atk,mCb.range),V.attackInfo(oCb.atk,oCb.range)
local vCb=eb.shieldDps(lCb,(tonumber(mCb.cd)or 2)*(rCb or 1),tCb.n,pCb,qCb,sCb,tCb.hits)
local wCb=eb.shieldDps(nCb,(tonumber(oCb.cd)or 2)*(rCb or 1),uCb.n,pCb,qCb,sCb,uCb.hits)
local xCb=math.max(0,((tonumber(oCb.range)or 0)-(tonumber(mCb.range)or 0))/math.max(1,tonumber(mCb.range)or 1))
return math.max(0,wCb-vCb)+vCb*xCb
end
function eb.shieldWork(yCb,zCb,ACb,BCb,CCb,DCb,ECb,FCb,GCb)
if(BCb or 0)<=0 then
return 0
end
local HCb=3*BCb*(CCb or 1)/math.max(1,DCb or 20)
if(ACb or 0)>=HCb then
return 0
end
return math.max(1,yCb or 1)*math.max(1,GCb or 1)/math.max(0.3,zCb or 2)*math.min(ECb or 0,FCb or 0)
end
function eb.holdGain(ICb,JCb,KCb,LCb)
if not ICb or(JCb or 0)<=0 then
return 0
end
local MCb,NCb=tonumber(ICb.stun)or 0,tonumber(ICb.slowTime)or 0
if MCb<=0 and NCb<=0 then
return 0
end
local OCb,PCb=MCb>0 and MCb or NCb,MCb>0 and 1 or(tonumber(ICb.slowPct)or 0.3)
local QCb=PCb*OCb/(OCb+(tonumber(ICb.ccCd)or 8))
local RCb=QCb/math.max(0.1,1-QCb)
return JCb*RCb*U.clamp(KCb or 0.5,0,1)*math.min(1,(tonumber(ICb.n)or 1)/2)/(1+(LCb or 0))
end
function eb.bleedGain(SCb,TCb,UCb,VCb)
if(SCb or 0)<=0 then
return 0
end
local WCb=TCb or 0
for XCb,YCb in ipairs(UCb or{})do
WCb=math.max(WCb,(tonumber(YCb.hp)or 0)*0.5)
end
return SCb*WCb*(VCb and 0.5 or 1)
end
function eb.bleedShare(ZCb,_Cb,aDb,bDb)
if ZCb<=0 or not _Cb then
return 0
end
if bDb then
return _Cb==0 and ZCb or ZCb/(_Cb+1)
end
return aDb<_Cb and ZCb/(_Cb-aDb)or 0
end
function eb.keepsUp(cDb,dDb,eDb,fDb,gDb)
local hDb=cDb.coming
if not(hDb and#hDb>0 and cDb.waveSec)then
return true
end
local iDb=cDb.eff or 1
local jDb=cDb.money-eDb
local kDb=(cDb.teamDps or 0)*(cDb.shieldK or 1)+(fDb or 0)*iDb+eb.dpsFor(dDb,math.max(0,jDb))*iDb
local lDb=(cDb.farmNow or 0)+(gDb or 0)
local mDb=(cDb.roadSec or 130)*U.clamp(cDb.cover or 0.6,0.1,1)
local nDb=cDb.hpAlive or 0
for oDb,pDb in ipairs(hDb)do
nDb=math.max(0,nDb+pDb.hp-kDb*cDb.waveSec)
local qDb=kDb*mDb
if nDb>qDb then
return false,oDb,qDb/math.max(1,nDb)
end
if oDb< #hDb then
kDb=kDb+eb.dpsFor(dDb,(pDb.reward or 0)+lDb)*iDb*(0.85^oDb)
end
end
return true
end
function eb.decide(rDb,sDb)
local tDb=U.clamp(sDb.cover or 0.6,0.1,1)
local uDb=math.max(O.clearSec,0.7*(sDb.roadSec or 50)*tDb)
local vDb=(sDb.clearSec or 0)>uDb
sDb.piling=sDb.piling and vDb
local wDb=sDb.attackers>0 and sDb.pressure<math.min(O.safeReach,tDb*0.75)and not sDb.piling and not vDb
local xDb=sDb.pressure>=math.min(O.dangerReach,tDb*0.9)or(sDb.piling and sDb.enemies>=18)
local yDb,zDb
for ADb,BDb in ipairs(rDb)do
if BDb.farm then
if O.farmUnits and BDb.gain>0 then
BDb.payback=BDb.cost/BDb.gain
if sDb.left-1>=BDb.payback+(sDb.farmSpare or O.farmSpare)and(not yDb or BDb.payback<yDb.payback)then
yDb=BDb
end
end
else
BDb.ratio=BDb.gain/math.max(1,BDb.cost)
if not zDb or BDb.ratio>zDb.ratio then
zDb=BDb
end
end
end
if sDb.leak and sDb.attackers>0 then
local CDb
for DDb,EDb in ipairs(rDb)do
local FDb=not sDb.airLeak or(EDb.e and bb.cardAir(EDb.e.id))
if EDb.place and not EDb.farm and not EDb.idol and FDb and EDb.cost<=sDb.money and not(EDb.e and V.allyBuff(EDb.e.id))and(not CDb or EDb.gain>CDb.gain)then
CDb=EDb
end
end
if CDb then
return CDb,string.format(xke[3650],math.floor(sDb.leak*100))
end
