function gb.footMove1()
local pQb={}
local function qQb(rQb)
if pQb[rQb]==nil then
local sQb,tQb=0,0
local uQb=P.learn[rQb]
if uQb and tonumber(uQb.n)and uQb.n>=1 then
local vQb=tonumber(uQb.eff)or 1
if(tonumber(uQb.v)or 0)<3 then
vQb=vQb*V.effRescale(rQb)
end
if(tonumber(uQb.v)or 0)<4 then
vQb=vQb*V.secRescale(rQb)
end
sQb,tQb=math.log(math.max(0.01,vQb))*uQb.n,uQb.n
end
local wQb,xQb=V.hiveEff(rQb,true)
if wQb then
sQb,tQb=sQb+math.log(math.max(0.01,wQb))*xQb,tQb+xQb
end
pQb[rQb]=V.nudgeFrom(sQb,tQb)
end
return pQb[rQb]
end
local yQb=0
for zQb,AQb in pairs(P.simCal or{})do
for BQb,CQb in ipairs({xke[3723],xke[3724]})do
for DQb,EQb in pairs(type(AQb)==xke[2016]and type(AQb[CQb])==xke[2016]and AQb[CQb]or{})do
if type(EQb)==xke[2016]and tonumber(EQb.k)and not tonumber(EQb.nu)then
