function jb.roomLearn(goc)
if goc or bb.kind~=xke[2036]or bb.roomLearned then
return
end
local hoc=P.dg.room
local ioc,joc=bb.pred,bb.calRun
if type(hoc)~=xke[2016]or hoc.seed==nil or type(ioc)~=xke[2016]or not ioc.won or type(joc)~=xke[2016]then
return
end
local function koc(loc,moc)
return type(loc)==xke[2016]and tonumber(loc[moc]or loc[tostring(moc)])or nil
end
local noc={}
for ooc=2,bb.wave()do
local poc,qoc=koc(joc.alive,ooc),koc(ioc.aliveAt,ooc)
if poc and qoc and poc>0 and qoc>0 then
table.insert(noc,poc/qoc)
end
end
if#noc<3 then
return
end
table.sort(noc)
local roc=noc[math.ceil(#noc/2)]
bb.roomLearned=true
if roc<=1.05 then
return
end
P.dg.roomK=type(P.dg.roomK)==xke[2016]and P.dg.roomK or{}
local soc=tostring(hoc.seed)
local toc=P.dg.roomK[soc]
local uoc=math.min(jb.ROOM_K_MAX,jb.roomK(soc)*roc)
P.dg.roomK[soc]={k=uoc,n=(type(toc)==xke[2016]and tonumber(toc.n)or 0)+1,at=os.time(),d=hoc.d}
bb.roomKUp=true
local voc={}
for woc,xoc in pairs(P.dg.roomK)do
table.insert(voc,{s=woc,at=type(xoc)==xke[2016]and tonumber(xoc.at)or 0})
end
table.sort(voc,function(yoc,zoc)
return yoc.at>zoc.at
end)
for Aoc=31,#voc do
P.dg.roomK[voc[Aoc].s]=nil
end
F.log(1,xke[3944],string.format(xke[4056],tostring(hoc.d),roc,uoc))
end
