local Doc=tostring(math.min(4,math.max(1,math.ceil(Coc/5))))
local Eoc=P.dg.depth[Doc]or{runs=0,wins=0}
Eoc.runs,Eoc.wins=(tonumber(Eoc.runs)or 0)+1,(tonumber(Eoc.wins)or 0)+(Boc and 1 or 0)
P.dg.depth[Doc]=Eoc
