function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local qqc,rqc={},0
for sqc,tqc in ipairs(workspace._UNITS:GetChildren())do
local uqc=tqc:FindFirstChild(xke[2079])
if uqc and uqc:FindFirstChild(xke[4073])and uqc.player.Value==nil and uqc:FindFirstChild(xke[4074])and tqc:FindFirstChild(xke[3272])then
local vqc=tostring(uqc.lane.Value)
if not qqc[vqc]then
qqc[vqc]=true
rqc=rqc+1
end
end
end
if rqc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,xke[2684],xke[4075])
return true
end
return false
end
bb.laneFirst=bb.laneFirst or U.now()
if rqc<bb.laneWant and U.now()-bb.laneFirst<bb.LANE_WAIT then
return false
end
local wqc,xqc={},{}
for yqc,zqc in ipairs(bb.samples)do
if qqc[tostring(zqc.lane)]then
table.insert(wqc,zqc)
end
end
if#wqc==0 then
bb.laneWant=nil
return true
end
for Aqc in pairs(qqc)do
table.insert(xqc,Aqc)
end
table.sort(xqc)
bb.samples,bb.laneCut=wqc,table.concat(xqc,xke[2330])
bb.countLanes()
local Bqc,Cqc=pcall(bb.buildCandidates)
if not Bqc then
F.log(1,xke[2402],xke[4076]..tostring(Cqc))
end
F.log(1,xke[2684],string.format(xke[4077],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local Dqc,Eqc=pcall(bb.planSpots)
bb.planning=nil
if not Dqc then
F.log(1,xke[2402],xke[4078]..tostring(Eqc))
end
end)
end
return true
end
