function bb.nearSpot(vIc,wIc,xIc)
local yIc,zIc=nil,9
for AIc,BIc in ipairs(vIc or{})do
local CIc=(BIc.X-wIc)^2+(BIc.Z-xIc)^2
if CIc<=zIc then
yIc,zIc=BIc,CIc
end
end
