local FIc=EIc and EIc[EIc.max]and tonumber(EIc[EIc.max].range)
return FIc or(N.Units[DIc]and tonumber(N.Units[DIc].range))or nil
end
function bb.studyMoves(GIc,HIc)
local IIc=V.rows(GIc.id)
local JIc=V.range(GIc.e.u,IIc.max)*HIc
local KIc=JIc*JIc
local LIc,MIc={},{}
local NIc,OIc=bb.hurtSamples(),bb.sandLine()
for PIc,QIc in ipairs(GIc.spots or{})do
local RIc,SIc,TIc,UIc,VIc=0,0,0,0,0
for WIc,XIc in ipairs(NIc)do
local YIc,ZIc=XIc.pos.X-QIc.X,XIc.pos.Z-QIc.Z
if YIc*YIc+ZIc*ZIc<=KIc then
TIc=TIc+1
local _Ic=math.min(49,math.floor(XIc.prog*50))
if _Ic<25 then
RIc=bit32 .bor(RIc,bit32 .lshift(1,_Ic))
else
SIc=bit32 .bor(SIc,bit32 .lshift(1,_Ic-25))
end
if XIc.prog-OIc<=0.3 then
UIc=UIc+1
elseif XIc.prog>=0.7 then
VIc=VIc+1
end
end
end
if TIc>0 then
local aJc=RIc..xke[2151]..SIc
local bJc=LIc[aJc]
if not bJc then
bJc={p=QIc,lo=RIc,hi=SIc,n=TIc,early=UIc,late=VIc}
LIc[aJc]=bJc
table.insert(MIc,bJc)
elseif TIc>bJc.n then
bJc.p,bJc.n,bJc.early,bJc.late=QIc,TIc,UIc,VIc
end
end
if PIc%40==0 then
task.wait()
end
end
local cJc={}
for dJc,eJc in ipairs(MIc)do
local fJc=false
for gJc,hJc in ipairs(MIc)do
if dJc~=gJc and hJc.n>=eJc.n and bit32 .band(eJc.lo,hJc.lo)==eJc.lo and bit32 .band(eJc.hi,hJc.hi)==eJc.hi and(hJc.lo~=eJc.lo or hJc.hi~=eJc.hi or hJc.n>eJc.n)then
fJc=true
break
end
end
if not fJc then
table.insert(cJc,eJc)
end
if dJc%40==0 then
task.wait()
end
end
local iJc,jJc={},{}
local function kJc(lJc)
if lJc and not jJc[lJc]then
jJc[lJc]=true
table.insert(iJc,lJc)
end
end
table.sort(cJc,function(mJc,nJc)
return mJc.n>nJc.n
end)
for oJc=1,math.min(bb.STUDY_K,#cJc)do
kJc(cJc[oJc].p)
end
table.sort(cJc,function(pJc,qJc)
return pJc.early>qJc.early
end)
kJc(cJc[1]and cJc[1].p)
kJc(cJc[2]and cJc[2].p)
table.sort(cJc,function(rJc,sJc)
return rJc.late>sJc.late
end)
kJc(cJc[1]and cJc[1].p)
kJc(cJc[2]and cJc[2].p)
local tJc=0
for uJc,vJc in ipairs((bb.hiveUnitSpots(bb.ld and bb.ld.map,GIc.id)))do
local wJc=tonumber(vJc.x)and tonumber(vJc.z)and bb.nearSpot(GIc.spots,tonumber(vJc.x),tonumber(vJc.z))or nil
if wJc and not jJc[wJc]then
kJc(wJc)
tJc=tJc+1
end
end
for xJc,yJc in ipairs(bb.hiveSpots(bb.ld and bb.ld.map))do
if tJc>=bb.STUDY_SHARED then
break
end
local zJc=false
for AJc,BJc in ipairs(type(yJc.units)==xke[2016]and yJc.units or{})do
local CJc=BJc==GIc.id and JIc or((bb.baseRange(BJc)or 0)*HIc)
if BJc==GIc.id or(CJc>0 and math.abs(CJc-JIc)<=0.3*JIc)then
zJc=true
break
end
end
local DJc=zJc and tonumber(yJc.x)and tonumber(yJc.z)and bb.nearSpot(GIc.spots,tonumber(yJc.x),tonumber(yJc.z))or nil
if DJc and not jJc[DJc]then
kJc(DJc)
tJc=tJc+1
end
end
return iJc,#MIc,#cJc,tJc
end
function bb.studyRun(EJc)
