end
local function iKc(jKc)
local kKc,lKc,mKc=0,0,0
for nKc,oKc in ipairs(MJc)do
local pKc=os.clock()
local qKc=gb.runRaw(HJc,IJc,{hpMul=oKc,layout=aKc(jKc),bg=true})
kKc,lKc,mKc=kKc+gb.objective(qKc),lKc+(tonumber(qKc.kills)or 0),mKc+(tonumber(qKc.wave)or 0)
task.wait(math.clamp((os.clock()-pKc)*3,0.25,EJc.pauseMax or 1.5))
if not GJc()then
