OJc.baseKills,OJc.baseWave=CKc.kills,CKc.wave
OJc.bestKills,OJc.bestWave=CKc.kills,CKc.wave
if NJc and NJc.aside==nil then
local DKc,EKc=rKc(CKc.spots),0
for FKc,GKc in ipairs(EJc.attackers)do
