local IKc=type(HKc)==xke[2016]and tonumber(HKc[1])and tonumber(HKc[3])and bb.nearSpot(GKc.spots,tonumber(HKc[1]),tonumber(HKc[3]))or nil
if IKc and IKc~=DKc[GKc.id]and not wKc(DKc,GKc.id,IKc)then
