end
local uLc=tLc.Position
if bb.blockedSpot(uLc)then
return nil
end
local vLc=(tonumber(sLc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(vLc*2,2.5,vLc*2)
bb.probe.CFrame=CFrame.new(uLc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return uLc
end
