table.insert(fNc.kills,math.floor(tonumber(jNc)))
while#fNc.kills>bb.LAYOUT_KEEP do
table.remove(fNc.kills,1)
end
end
while#fNc.sec>bb.LAYOUT_KEEP do
table.remove(fNc.sec,1)
end
while#fNc.wave>bb.LAYOUT_KEEP do
table.remove(fNc.wave,1)
end
end
function bb.layoutJudge(kNc,lNc,mNc,nNc,oNc)
oNc=oNc or xke[4259]
local pNc,qNc=tonumber(kNc and kNc.runs)or 0,tonumber(lNc and lNc.runs)or 0
if pNc<1 or qNc<bb.LAYOUT_CONTROL then
return nil
end
if nNc and type(kNc.kills)==xke[2016]and type(lNc.kills)==xke[2016]and#kNc.kills>=1 and#lNc.kills>=bb.LAYOUT_CONTROL then
local rNc,sNc=bb.labMedian(kNc.kills),bb.labMedian(lNc.kills)
if rNc and sNc and rNc<sNc*0.97 and(#kNc.kills>=2 or rNc<sNc*0.85)then
return string.format(xke[4260],rNc,sNc,oNc)
end
return nil
end
local tNc,uNc=(tonumber(kNc.wins)or 0)/pNc,(tonumber(lNc.wins)or 0)/qNc
if not mNc and uNc>=0.5 then
if tNc+0.25<uNc and(pNc>=2 or(tNc==0 and uNc>=0.9 and qNc>=3))then
return string.format(xke[4261],tonumber(kNc.wins)or 0,pNc,pNc==1 and xke[937]or xke[1864],tonumber(lNc.wins)or 0,qNc,oNc)
end
local vNc,wNc=bb.labMedian(kNc.sec),bb.labMedian(lNc.sec)
if vNc and wNc and vNc>wNc*1.10 and(#kNc.sec>=2 or vNc>wNc*1.25)then
return string.format(xke[4262],math.floor(vNc/60),vNc%60,math.floor(wNc/60),wNc%60,oNc)
end
return nil
end
local xNc,yNc=bb.labMedian(kNc.wave),bb.labMedian(lNc.wave)
if xNc and yNc and xNc<yNc-math.max(1,yNc*0.03)and(pNc>=2 or xNc<yNc*0.85)then
return string.format(xke[4263],xNc,yNc,oNc)
end
return nil
end
function bb.layoutResult(zNc,ANc)
local BNc=bb.info
local CNc=bb.layoutSrc
if not(BNc and CNc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not BNc.timeLimit then
return
end
local DNc=bb.wave()
local ENc=bb.layoutRecFor(BNc,true)
ENc.at=os.time()
local FNc=BNc.timeLimit~=nil
local GNc=BNc.killScore and true or nil
local HNc=GNc and(bb.killsEnd or bb.realKills())or nil
if CNc==xke[4229]then
local INc=bb.bookFor(BNc)
if not INc then
return
end
INc.real=type(INc.real)==xke[2016]and INc.real or{}
bb.layoutAdd(INc.real,zNc,ANc,DNc,HNc)
local JNc=INc.aside==nil and bb.layoutJudge(INc.real,ENc.own,FNc,GNc)or nil
if JNc then
INc.aside={at=os.time(),why=JNc}
F.log(1,xke[4173],string.format(xke[4264],JNc))
end
elseif CNc==xke[3608]then
ENc.hiveUnit=type(ENc.hiveUnit)==xke[2016]and ENc.hiveUnit or{}
local KNc=ENc.hiveUnit
bb.layoutAdd(KNc,zNc,ANc,DNc,HNc)
local LNc=bb.bookFor(BNc)
local MNc=LNc and type(LNc.real)==xke[2016]and(tonumber(LNc.real.runs)or 0)>=bb.LAYOUT_CONTROL
local NNc=MNc and LNc.real or ENc.own
local ONc=bb.layoutJudge(KNc,NNc,FNc,GNc,MNc and xke[4265]or nil)
if ONc then
KNc.aside,KNc.why=os.time(),ONc
F.log(1,xke[4173],string.format(xke[4266],ONc))
elseif(tonumber(KNc.runs)or 0)>=bb.HIVE_TRIALS then
local PNc=NNc and bb.layoutJudge(NNc,KNc,FNc,GNc,xke[4267])
if PNc and LNc and type(bb.hiveUnitPlan)==xke[2016]then
for QNc,RNc in pairs(bb.hiveUnitPlan)do
LNc.spots[QNc]=RNc
end
LNc.real={runs=KNc.runs,wins=KNc.wins,sec=KNc.sec,wave=KNc.wave,kills=KNc.kills}
LNc.hive,LNc.aside=os.time(),nil
ENc.hiveUnit=nil
F.log(1,xke[4173],string.format(xke[4268],PNc))
else
KNc.aside,KNc.why=os.time(),xke[4269]
F.log(1,xke[4173],xke[4270])
end
end
else
ENc[CNc]=type(ENc[CNc])==xke[2016]and ENc[CNc]or{}
local SNc=ENc[CNc]
bb.layoutAdd(SNc,zNc,ANc,DNc,HNc)
if CNc==xke[3607]and SNc.aside==nil then
local TNc=bb.layoutJudge(SNc,ENc.own,FNc,GNc)
if TNc then
SNc.aside,SNc.why=os.time(),TNc
F.log(1,xke[4173],string.format(xke[4271],TNc))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={xke[4272],xke[4273],xke[4274],xke[4275]}
function bb.controlSpot(UNc,VNc)
if not bb.killZone()then
return nil
end
local WNc=gb.holds
if not WNc(UNc.id)or V.toggleOf(UNc.id)then
return nil
end
local XNc,YNc,ZNc,_Nc=1,0,0,{}
local aOc=bb.hurtSamples()
for bOc,cOc in ipairs(bb.mine or{})do
local dOc=cOc._stats
local eOc=dOc.id.Value
if dOc:FindFirstChild(xke[2268])and not V.isFarm(eOc)and not V.allyBuff(eOc)then
local fOc,gOc=U.flat(cOc:GetPivot().Position),dOc.range.Value
if WNc(eOc)and not V.toggleOf(eOc)then
ZNc=ZNc+1
table.insert(_Nc,{p=fOc,r=gOc})
else
for hOc,iOc in ipairs(aOc)do
if(U.flat(iOc.pos)-fOc).Magnitude<=gOc then
XNc,YNc=math.min(XNc,iOc.prog),math.max(YNc,iOc.prog)
end
end
end
end
end
if YNc<=XNc then
XNc,YNc=0.75,0.98
end
local jOc=(VNc or ZNc)+1
local kOc=({XNc,YNc,(XNc+YNc)/2,XNc-(YNc-XNc)/2})[jOc]
if not kOc then
return nil
end
local lOc=V.range(UNc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local mOc={}
for nOc,oOc in ipairs(bb.cands)do
local pOc,qOc,rOc=U.flat(oOc),0,0
for sOc,tOc in ipairs(aOc)do
if(U.flat(tOc.pos)-pOc).Magnitude<=lOc then
rOc=rOc+1
if math.abs(tOc.prog-kOc)<=0.05 then
qOc=qOc+1
local uOc=U.flat(tOc.pos)
for vOc,wOc in ipairs(_Nc)do
if(uOc-wOc.p).Magnitude<=wOc.r then
qOc=qOc-0.5
break
end
end
end
end
end
if qOc>0 then
table.insert(mOc,{pos=oOc,sc=qOc,cov=rOc})
end
if nOc%60==0 then
task.wait()
end
end
table.sort(mOc,function(xOc,yOc)
return xOc.sc>yOc.sc
end)
for zOc,AOc in ipairs(mOc)do
local BOc=bb.valid(AOc.pos,UNc.data)
if BOc then
F.log(1,xke[4112],string.format(xke[4276],V.name(UNc.id),bb.CONTROL_WORDS[jOc],math.floor(kOc*100+0.5)))
return BOc,AOc.cov,kOc
end
if zOc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(COc)
local DOc,EOc=gb.holds(COc.id)
if not DOc then
return nil
end
if V.killFed(COc.id)then
return nil
end
local FOc,GOc={},0
for HOc,IOc in ipairs(bb.mine or{})do
local JOc=IOc._stats
local KOc=JOc.id.Value
if JOc:FindFirstChild(xke[2268])and not V.isFarm(KOc)and not V.allyBuff(KOc)and KOc~=COc.id then
local LOc,MOc=pcall(bb.liveDps,IOc,KOc)
MOc=LOc and tonumber(MOc)or 0
if MOc>0 then
table.insert(FOc,{p=U.flat(IOc:GetPivot().Position),r=JOc.range.Value,d=MOc})
GOc=GOc+MOc
end
end
end
if#FOc==0 or GOc<=0 then
return nil
end
local NOc=bb.hurtSamples()
local OOc={}
for POc,QOc in ipairs(NOc)do
local ROc,SOc=U.flat(QOc.pos),0
for TOc,UOc in ipairs(FOc)do
if(ROc-UOc.p).Magnitude<=UOc.r then
SOc=SOc+UOc.d
end
end
OOc[POc]=SOc/GOc
end
local VOc=V.range(COc.u,math.min(tonumber(EOc)or 0,3,V.rows(COc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local WOc,XOc,YOc
for ZOc,_Oc in ipairs(bb.cands)do
local aPc,bPc,cPc=U.flat(_Oc),0,0
for dPc,ePc in ipairs(NOc)do
if(U.flat(ePc.pos)-aPc).Magnitude<=VOc then
bPc=bPc+OOc[dPc]
cPc=cPc+1
end
end
if bPc>0 and(not XOc or bPc>XOc)then
local fPc=bb.valid(_Oc,COc.data)
if fPc then
WOc,XOc,YOc=fPc,bPc,cPc
end
end
if ZOc%40==0 then
task.wait()
end
end
if not WOc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[COc.id]then
bb.holdSaid[COc.id]=true
F.log(1,xke[4112],string.format(xke[4277],V.name(COc.id)))
end
return WOc,YOc or 0
end
function bb.bestSpot(gPc,hPc,iPc)
if bb.hybridHill and not gPc._hillTry and type(gPc.data)==xke[2016]and gPc.data.hybrid_placement and not gPc.data.hill_unit then
local jPc=setmetatable({data=bb.hillData(gPc.data),_hillTry=true},{__index=gPc})
local kPc,lPc,mPc=pcall(bb.bestSpot,jPc,hPc,iPc)
if kPc and lPc then
return lPc,mPc
end
end
if bb.focus and not hPc and not iPc and not V.allyBuff(gPc.id)then
local nPc,oPc=bb.focusSpot(gPc)
if nPc then
return nPc,oPc
end
end
if O.fishiFollow and not hPc and not iPc then
local pPc,qPc,rPc,sPc,tPc=pcall(bb.drownBoss)
if pPc and qPc and not rPc and tPc and tPc[gPc.id]then
local uPc,vPc,wPc=pcall(bb.drownSpot,gPc,qPc)
if uPc and vPc then
return vPc,wPc
end
end
end
if not hPc and not iPc and not(bb.depth and bb.depth.leak)then
local xPc,yPc,zPc=pcall(bb.controlSpot,gPc)
if xPc and yPc then
return yPc,zPc
end
local APc,BPc,CPc=pcall(bb.holdSpot,gPc)
if APc and BPc then
return BPc,CPc
end
end
local DPc=bb.depth and bb.depth.leak
if bb.layout and bb.layout[gPc.id]and not hPc and not iPc then
local EPc=false
for FPc,GPc in ipairs(bb.mine or{})do
local HPc=GPc._stats:FindFirstChild(xke[2392])
if HPc and HPc.Value==gPc.uuid then
EPc=true
break
end
end
if not EPc then
for IPc,JPc in ipairs(bb.layout[gPc.id])do
local KPc=bb.valid(JPc,gPc.data)
if KPc and bb.sandLine()>0 and bb.cover(KPc,V.range(gPc.u,V.rows(gPc.id).max)*((bb.info and tonumber(bb.info.rangeScale))or 1))<=0 then
KPc=nil
end
if KPc and DPc then
local LPc,MPc,NPc=false,U.flat(KPc),V.range(gPc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local OPc=bb.depth and bb.depth.leakLane and tostring(bb.depth.leakLane)or nil
for PPc,QPc in ipairs(bb.hurtSamples())do
if QPc.prog>=DPc+0.02 and(not OPc or tostring(QPc.lane)==OPc)and(U.flat(QPc.pos)-MPc).Magnitude<=NPc then
LPc=true
break
end
end
if not LPc then
KPc=nil
end
end
if KPc then
bb.layoutUsed=bb.layoutUsed or{}
bb.layoutUsed[gPc.id]=KPc
return KPc,bb.cover(KPc,V.range(gPc.u,math.min(3,V.rows(gPc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1))
end
end
end
end
local RPc=gPc.data
local SPc=bb.depth
local TPc,UPc=bb.hurtSamples(),bb.sandLine()
local VPc
if iPc then
VPc=1
for WPc,XPc in ipairs(bb.mine or{})do
local YPc=XPc._stats
if not V.isFarm(YPc.id.Value)and not(YPc:FindFirstChild(xke[2392])and YPc.uuid.Value==gPc.uuid)then
local ZPc,_Pc=U.flat(XPc:GetPivot().Position),YPc.range.Value
for aQc,bQc in ipairs(TPc)do
if bQc.prog<VPc and(U.flat(bQc.pos)-ZPc).Magnitude<=_Pc then
VPc=bQc.prog
end
end
end
end
if V.ENTRY[gPc.id]or(bb.studyEntry and gPc.id==bb.trialId)then
VPc=math.min(VPc,UPc+0.1)
end
end
local cQc=(bb.info and tonumber(bb.info.rangeScale))or 1
local dQc=V.range(gPc.u,(SPc and SPc.leak)and 0 or math.min(3,V.rows(gPc.id).max))*cQc
local eQc=(bb.kind==xke[2036]or bb.style==xke[3708]or bb.style==xke[3709])and not hPc and not(SPc and SPc.leak)and not V.isFarm(gPc.id)and V.range(gPc.u,V.rows(gPc.id).max)*cQc or nil
local fQc=V.allyBuff(gPc.id)
if bb.killZone()and not hPc and not iPc and not fQc and not(SPc and SPc.leak)and not V.isFarm(gPc.id)then
local gQc=eQc or dQc
local hQc={}
for iQc,jQc in ipairs(bb.mine or{})do
local kQc=jQc._stats
local lQc=kQc.id.Value
if not V.isFarm(lQc)and not V.allyBuff(lQc)and kQc:FindFirstChild(xke[2268])then
table.insert(hQc,{p=U.flat(jQc:GetPivot().Position),r=kQc.range.Value})
end
end
local mQc={}
for nQc,oQc in ipairs(TPc)do
local pQc=0
local qQc=U.flat(oQc.pos)
for rQc,sQc in ipairs(hQc)do
if(qQc-sQc.p).Magnitude<=sQc.r then
pQc=pQc+1
end
end
mQc[nQc]=pQc
end
local tQc,uQc,vQc
local wQc=0
for xQc,yQc in ipairs(bb.cands)do
local zQc=bb.valid(yQc,RPc)
wQc=wQc+1
if wQc%40==0 then
task.wait()
end
if zQc then
local AQc,BQc,CQc=U.flat(zQc),0,0
for DQc,EQc in ipairs(TPc)do
if(U.flat(EQc.pos)-AQc).Magnitude<=gQc then
CQc=CQc+1
if EQc.prog>=0.6 then
BQc=BQc+(EQc.prog-0.5)*(1+mQc[DQc])
end
end
end
if not uQc or BQc>uQc then
tQc,uQc,vQc=zQc,BQc,CQc
end
end
end
if tQc and uQc>0 then
if not bb.zoneSaid then
bb.zoneSaid=true
F.log(1,xke[4112],xke[4278])
end
return tQc,vQc or 0
end
end
if bb.style==xke[3709]and not hPc and not iPc and not fQc and not(SPc and SPc.leak)and not V.isFarm(gPc.id)then
local FQc=eQc or dQc
local GQc,HQc,IQc
local JQc=0
for KQc,LQc in ipairs(bb.cands)do
local MQc=bb.valid(LQc,RPc)
JQc=JQc+1
if JQc%40==0 then
task.wait()
end
if MQc then
local NQc,OQc,PQc=U.flat(MQc),0,0
for QQc,RQc in ipairs(TPc)do
if(U.flat(RQc.pos)-NQc).Magnitude<=FQc then
PQc=PQc+1
if RQc.prog-UPc<=bb.FAST_ROAD then
OQc=OQc+1.5-(RQc.prog-UPc)
end
end
end
if not HQc or OQc>HQc then
GQc,HQc,IQc=MQc,OQc,PQc
end
end
end
if GQc and HQc>0 then
return GQc,IQc or 0
end
end
local SQc=bb.infinite and bb.trainee and not iPc and gPc.uuid~=bb.trainee and not V.isFarm(gPc.id)and not fQc and not hPc and not(SPc and SPc.leak)and(bb.pressure or 0)<O.dangerReach and ib.ZONE or nil
local TQc=SQc and V.range(gPc.u,V.rows(gPc.id).max)or nil
local UQc,VQc=V.types(gPc.id)
local WQc=fQc and{}or bb.fieldBuffers()
local XQc,YQc={},0
if fQc then
XQc=bb.buffShort(fQc)
local ZQc=false
if V.stackCap(fQc.attack)then
for _Qc,aRc in ipairs(XQc)do
if aRc.n>0 then
ZQc=true
break
end
end
end
for bRc,cRc in ipairs(XQc)do
cRc.w=(ZQc and cRc.n==0)and 0.1 or 1
YQc=YQc+cRc.full*cRc.w
end
end
local dRc=O.community and not VPc and N.TIPS[gPc.id]
local eRc=((dRc and dRc.spot==xke[2004])or(not VPc and bb.needLastLine(gPc)))and not(SPc and SPc.leak)
local fRc=not(VPc or hPc or fQc)and bb.mergeSpot(gPc)
local gRc=fRc and V.range(gPc.u,0)*0.7
local hRc,iRc
if hPc and V.isFarm(gPc.id)then
hRc,iRc=bb.farmMergeSpot(gPc)
iRc=hRc and iRc*0.8
end
local jRc=hPc and not hRc and bb.random and V.isFarm(gPc.id)and bb.farmMergeOk()and{}or nil
local kRc=bb.cands
local lRc,mRc=hRc or fRc,hRc and iRc or gRc
if lRc and mRc and mRc>0 then
kRc=table.clone(bb.cands)
for nRc,oRc in ipairs({0.5,0.7,0.9})do
for pRc=0,11 do
local qRc=pRc*math.pi/6
table.insert(kRc,lRc+Vector3 .new(math.cos(qRc),0,math.sin(qRc))*mRc*oRc)
end
