local rRc,sRc,tRc
local uRc=0
local vRc=P.maps[bb.mapKey()]and P.maps[bb.mapKey()].dens
for wRc,xRc in ipairs(kRc)do
local yRc=bb.valid(xRc,RPc)
uRc=uRc+1
if uRc%40==0 then
task.wait()
end
if yRc then
local zRc
if hPc then
zRc= -bb.cover(yRc,dQc)
elseif VPc then
zRc=0
local ARc=U.flat(yRc)
for BRc,CRc in ipairs(TPc)do
if(U.flat(CRc.pos)-ARc).Magnitude<=dQc then
zRc=zRc+(CRc.prog<=VPc+0.05 and 1 or 0.1)
end
end
elseif SQc then
zRc=0
local DRc=U.flat(yRc)
for ERc,FRc in ipairs(TPc)do
local GRc=(U.flat(FRc.pos)-DRc).Magnitude
if FRc.prog<SQc then
if GRc<=TQc then
zRc=zRc-2
end
elseif GRc<=dQc then
zRc=zRc+1
end
end
elseif eRc then
zRc=0
local HRc=U.flat(yRc)
for IRc,JRc in ipairs(TPc)do
if(U.flat(JRc.pos)-HRc).Magnitude<=dQc then
zRc=zRc+JRc.prog*JRc.prog
end
end
elseif fQc and YQc>0 then
local KRc=0
for LRc,MRc in ipairs(XQc)do
local NRc=(U.flat(MRc.pos)-U.flat(yRc)).Magnitude
if NRc<=dQc then
KRc=KRc+MRc.full*MRc.w*(1.1-0.1*NRc/math.max(1,dQc))
end
end
zRc=KRc/YQc*100+bb.cover(yRc,dQc,true)*0.05
else
local ORc=bb.cover(yRc,dQc,true,SPc)
if eQc then
ORc=bb.cover(yRc,eQc)+ORc*0.25
end
zRc=ORc+(vRc and 0 or(1-bb.progressAt(yRc))*0.5)
local PRc=0
for QRc,RRc in ipairs(WQc)do
local SRc=RRc.b.types[VQc]
if SRc and(U.flat(RRc.pos)-U.flat(yRc)).Magnitude<=RRc.range then
PRc=math.max(PRc,math.min(SRc,PRc+SRc*RRc.b.uptime))
end
end
zRc=zRc*(1+PRc)
end
if fRc and(U.flat(fRc)-U.flat(yRc)).Magnitude<=gRc then
zRc=zRc+1e6
end
if hRc and(U.flat(hRc)-U.flat(yRc)).Magnitude<=iRc then
zRc=zRc+1e6
end
if jRc then
table.insert(jRc,{p=yRc,sc=zRc})
end
if not sRc or zRc>sRc then
rRc,sRc,tRc=yRc,zRc,bb.cover(yRc,dQc)
end
end
end
if fQc and#XQc>0 and rRc then
local TRc=false
for URc,VRc in ipairs(XQc)do
if(U.flat(VRc.pos)-U.flat(rRc)).Magnitude<=dQc then
TRc=true
break
end
end
if not TRc then
return nil,0
end
end
if jRc and#jRc>0 then
table.sort(jRc,function(WRc,XRc)
return WRc.sc>XRc.sc
end)
for YRc=1,math.min(15,#jRc)do
local ZRc,_Rc=jRc[YRc].p,0
for aSc=0,7 do
local bSc=aSc*math.pi/4
if bb.valid(ZRc+Vector3 .new(math.cos(bSc),0,math.sin(bSc))*5,RPc)then
_Rc=_Rc+1
end
if _Rc>=2 then
