if hSc<dSc then
dSc,eSc=hSc,gSc.pos
end
end
local iSc=eSc and U.flat(eSc-cSc)or Vector3 .new(0,0,-1)
return iSc.Magnitude>0.01 and iSc.Unit or Vector3 .new(0,0,-1)
end
