bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=jSc.id,x=math.floor(mSc.X),z=math.floor(mSc.Z),cover=math.floor((nSc or 0)+0.5),why=tostring(kSc):sub(1,90)})
F.status(xke[4176],string.format(xke[4285],V.name(jSc.id),kSc))
bb.placedAt=bb.placedAt or{}
bb.placedAt[jSc.uuid]=(bb.placedAt[jSc.uuid]or 0)+1
return true
end
if oSc>=(jSc.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[jSc.uuid]=(bb.placeFail[jSc.uuid]or 0)+1
if bb.placeFail[jSc.uuid]>=2 then
bb.noSpot[jSc.uuid]=3
F.log(1,xke[4112],string.format(xke[4286],V.name(jSc.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if qSc and oSc>=(jSc.data.cost or 0)and not bb.random then
local sSc=bb.spotKey(mSc)
bb.refused[sSc]=true
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[jSc.uuid]=(bb.unitRefusals[jSc.uuid]or 0)+1
if not bb.crowded()then
local tSc=bb.mapKey()
P.blocked[tSc]=P.blocked[tSc]or{}
if not bb.refusedRun[sSc]then
P.blocked[tSc][sSc]=(tonumber(P.blocked[tSc][sSc])or 0)+1
bb.refusedRun[sSc]=true
P.blockedAt[tSc]=P.blockedAt[tSc]or{}
P.blockedAt[tSc][sSc]=os.time()
end
if bb.unitRefusals[jSc.uuid]>=3 then
local uSc=math.max(1,bb.count(jSc.uuid))
if P.caps[jSc.uuid]~=uSc or not V.learnedCap(jSc.uuid)then
P.caps[jSc.uuid],P.capsAt[jSc.uuid]=uSc,os.time()
F.log(1,xke[4112],string.format(xke[4287],V.name(jSc.id),uSc))
end
end
elseif bb.unitRefusals[jSc.uuid]>=3 and(bb.noSpot[jSc.uuid]or 0)<3 then
