F.log(1,xke[4112],string.format(xke[4288],V.name(jSc.id)))
end
if bb.refusals>=bb.REFUSE_FREE then
if not bb.placePause then
F.log(1,xke[4112],string.format(xke[4289],bb.refusals,bb.REFUSE_PAUSE))
end
bb.placePause=U.now()+bb.REFUSE_PAUSE
end
F.log(2,xke[4112],xke[4290]..sSc..xke[2942]..V.name(jSc.id))
F.saveSoon()
end
return false
end
