local tdd=rdd and rdd:FindFirstChild(xke[2268])
if sdd and tdd and not V.isFarm(sdd.Value)and not V.allyBuff(sdd.Value)then
local udd,vdd=U.flat(qdd:GetPivot().Position),tdd.Value
if(not mdd.fly or bb.canAir(qdd))and(udd-odd).Magnitude>vdd then
for wdd,xdd in ipairs(bb.samples or{})do
if xdd.prog>mdd.prog and(U.flat(xdd.pos)-udd).Magnitude<=vdd then
ndd=ndd+1
break
end
end
end
end
end
return ndd
end
function bb.leakStep(ydd)
