end
local Add=workspace:FindFirstChild(xke[4546])and workspace._BASES:FindFirstChild(xke[4073])
local Bdd=Add and Add:FindFirstChild(xke[4295])and Add.base:FindFirstChild(xke[4296])
local Cdd=Bdd and Bdd:FindFirstChildOfClass(xke[2411])
