if Jdd.m then
Gdd[Jdd.m]=true
local Kdd,Ldd=tonumber(Jdd.hp)or 0,tonumber(Jdd.prog)or 0
local Mdd=Fdd[Jdd.m]
if not Mdd then
Fdd[Jdd.m]={t=Edd,hp=Kdd,prog=Ldd}
else
if Edd-Mdd.t>=bb.LEAK_WIN then
