for ded,eed in ipairs(bb.samples or{})do
if eed.prog>ced and(U.flat(eed.pos)-bed).Magnitude<=_dd then
ced=eed.prog
end
end
aed={r=_dd,far=ced}
bb.coverMax[Xdd]=aed
