if#Yvd<=3900 then
return Yvd
end
if Xvd.mapData then
Xvd.mapData.dens=nil
end
Yvd=U.json(Xvd)
if#Yvd<=3900 then
return Yvd
end
Xvd.placed,Xvd.plan=nil,nil
