function ob.session()
local fEd,gEd=pcall(ob.sessionBody)
if not fEd then
F.log(1,xke[2402],xke[5085]..tostring(gEd))
return false
end
P.hook.sessAt,P.hook.sessRuns=os.time(),tonumber(P.sess and P.sess.runs)or 0
return ob.queue(xke[5086],gEd)
end
function ob.sessionDue()
local hEd=P.sess
if type(hEd)~=xke[2016]then
return
end
if P.hook.sessOf~=hEd.at then
P.hook.sessOf,P.hook.sessAt,P.hook.sessRuns=hEd.at,os.time(),tonumber(hEd.runs)or 0
end
local iEd=math.max(15,tonumber(O.hookEvery)or 60)*60
if os.time()-(tonumber(P.hook.sessAt)or 0)<iEd then
return
end
if(tonumber(hEd.runs)or 0)<=(tonumber(P.hook.sessRuns)or 0)then
