return true
end
if ASd==ESd.PageUp or ASd==ESd.PageDown then
local FSd={}
for GSd,HSd in pairs(DSd._tabs)do
table.insert(FSd,{name=GSd,y=HSd.btn.AbsolutePosition.Y,on=HSd.page.Visible})
