if MSd.on then
KSd=LSd
end
end
KSd=(KSd-1+(ASd==ESd.PageDown and 1 or-1))% #FSd+1
CSd.setFocus(nil)
DSd:SelectTab(FSd[KSd].name)
return true
end
if ASd==ESd.Tab or ASd==ESd.Down or ASd==ESd.Up then
