return true
end
local OSd=ASd==ESd.Up or(ASd==ESd.Tab and BSd)
local PSd=table.find(NSd,CSd.cur)
if not PSd then
PSd=OSd and#NSd or 1
else
PSd=(PSd-1+(OSd and-1 or 1))% #NSd+1
end
CSd.setFocus(NSd[PSd])
return true
end
if not CSd.cur then
return false
end
if ASd==ESd.Return or ASd==ESd.KeypadEnter or ASd==ESd.Space then
if CSd.cur.activate then
CSd.cur.activate()
end
return true
end
if ASd==ESd.Left or ASd==ESd.Right then
if CSd.cur.adjust then
CSd.cur.adjust(ASd==ESd.Right and 1 or-1)
end
return true
end
if ASd==ESd.Escape then
CSd.setFocus(nil)
return true
end
return false
end
